    function uiIsDark(w) {
        if (LOGO_THEME === "dark") return true;
        if (LOGO_THEME === "light") return false;
        try {
            var c = w.graphics.backgroundColor.color;
            if (c && c.length >= 3) return ((c[0] + c[1] + c[2]) / 3) < 0.5;
        } catch (eBg) {}
        try {
            var b = app.preferences.getRealPreference("uiBrightness");
            if (b >= 0 && b <= 1) return b < 0.5;
        } catch (ePr) {}
        return true;
    }
    function addLogo(parent, w) {
        try {
            var key = uiIsDark(w) ? "dark" : "light";
            var f = new File(Folder.temp.fsName + "/signpack_logo_" + key + ".png");
            f.encoding = "BINARY";
            if (f.open("w")) { f.write(LOGO_DATA[key]); f.close(); }
            if (!f.exists || f.length < 50) return null;
            return parent.add("image", undefined, f);
        } catch (eLogo) { return null; }
    }

